// ============================================================
//  Capri : discussion en mode balade (panneau + tablette)
//  Mets ce fichier dans le dossier du projet (là où est index.html),
//  puis tape dans le terminal de VS Code :   node appliquer-discussion.js
//  Il modifie index.html tout seul (une copie de sauvegarde est créée)
//  et crée les 6 images de poses (capri_tab_*.png).
// ============================================================
const fs = require('fs');
const path = require('path');

const DOSSIER = __dirname;
const FICHIER = path.join(DOSSIER, 'index.html');
const SAUVEGARDE = path.join(DOSSIER, 'index.html.avant-discussion.bak');
const MARQUE = 'DISCUSSION-BALADE';

const IMAGES = {
  "capri_tab_cote_droite.png": "",
  "capri_tab_cote_gauche.png": "",
  "capri_tab_diag_haut.png": "",
  "capri_tab_diag_bas.png": "",
  "capri_tab_haut.png": "",
  "capri_tab_lecture.png": ""
};

// ---------- CSS ajouté ----------
const CSS = String.raw`
  /* ===== DISCUSSION-BALADE : bouton, panneau d'écriture et tablette ===== */
  #discBtn { display: none; position: fixed; z-index: 62; cursor: pointer; }
  #discBtn:hover .tag-in { filter: brightness(1.5); }
  #discPanel { display: none; position: fixed; z-index: 63; width: 340px; transform-origin: top right; }
  #discPanel .rb-in { padding: 14px 16px 14px 14px; }
  #discPanel .reboot-sous { margin: 8px 0 8px; font-size: 11px; letter-spacing: 2px; }
  #discBar { display: flex; gap: 6px; align-items: center; }
  #discCompress, #discFermer {
    flex-shrink: 0; height: 28px; padding: 0; background: #000; color: var(--cyan);
    border: 1px solid var(--cyan); display: flex; align-items: center; justify-content: center;
    font-family: inherit; font-size: 14px; touch-action: none;
  }
  #discCompress { width: 38px; cursor: grab; box-shadow: 0 0 7px rgba(39, 230, 255, 0.55); }
  #discCompress:hover { background: rgba(39, 230, 255, 0.2); }
  #discCompress:active { cursor: grabbing; }
  #discFermer { width: 28px; color: var(--cadre); border-color: var(--cadre); cursor: pointer; }
  #discFermer:hover { background: rgba(255, 77, 90, 0.2); }
  #discInput {
    display: block; width: 100%; box-sizing: border-box; height: 84px; resize: none;
    background: #000; color: #e8fff6; border: 1px solid var(--cadre); padding: 8px;
    font-family: inherit; font-size: 13px; outline: none; user-select: text;
  }
  #discInput:focus { border-color: var(--vert); box-shadow: 0 0 8px rgba(0, 255, 163, 0.35); }
  #discHint { margin-top: 8px; font-size: 10px; letter-spacing: 1.5px; line-height: 1.5; color: var(--cyan); }
  #discHint.mal { color: var(--rouge); text-shadow: 0 0 6px rgba(255, 46, 99, 0.6); }
  /* La petite tablette noire */
  #discTab {
    display: none; position: fixed; left: 0; top: 0; z-index: 99; width: 64px; height: 46px;
    margin: -23px 0 0 -32px; pointer-events: none; will-change: transform;
    background: linear-gradient(145deg, #2c2c31, #0b0b0d); border: 2px solid #050505; border-radius: 3px;
    box-shadow: 0 0 0 1px rgba(39, 230, 255, 0.6), 0 0 16px rgba(39, 230, 255, 0.55);
  }
  #discTab::after {
    content: ""; position: absolute; inset: 5px;
    background: repeating-linear-gradient(0deg, rgba(39, 230, 255, 0.2) 0 1px, transparent 1px 4px);
  }
  /* Bulle plus large pour les réponses */
  .bulle-in.longue { max-width: 340px; }
`;

// ---------- HTML ajouté ----------
const HTML = String.raw`
  <!-- DISCUSSION-BALADE : bouton dans un coin, panneau d'écriture, tablette -->
  <div id="discBtn"><div class="tag-cadre"><div class="tag-in" style="padding:5px 14px 6px 9px"><div class="tag-t" style="font-size:12px;letter-spacing:4px">PARLER</div></div></div></div>
  <div id="discPanel">
    <div class="rb-cadre cy"><div class="rb-in">
      <div class="rb-tete">
        <div class="reboot-titre pt" id="discTitre">LIEN CAPRI</div>
        <div id="discBar">
          <button id="discFermer" title="Fermer">✕</button>
          <button id="discCompress" title="Maintiens et glisse vers Capri">
            <svg width="22" height="18" viewBox="0 0 22 18" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="6" y="4" width="10" height="10"/><path d="M1 1l4 4M21 1l-4 4M1 17l4-4M21 17l-4-4"/></svg>
          </button>
        </div>
      </div>
      <div class="reboot-sous">// MESSAGE POUR CAPRI</div>
      <textarea id="discInput" placeholder="Écris à Capri..." autocomplete="off" spellcheck="false"></textarea>
      <div id="discHint"></div>
      <div class="rb-scan"></div>
    </div></div>
  </div>
  <div id="discTab"></div>
`;

// ---------- JavaScript ajouté ----------
const JS = String.raw`
  /* DISCUSSION-BALADE */
  // ===== Discussion en mode balade =====
  // Un bouton dans un coin ouvre un panneau d'écriture. Le bouton en haut à droite du panneau le comprime
  // en tablette noire : tant que tu restes appuyé, Capri tend les bras vers la tablette (selon sa position).
  // Quand tu relâches, la tablette vole jusqu'à ses mains, elle la lit, puis sa réponse s'affiche dans une bulle.
  const COIN_DISCUSSION = 'haut-gauche';  // 'haut-gauche', 'haut-droite', 'bas-gauche' ou 'bas-droite'
  const MARGE_COIN = 18;                  // distance entre le bouton / le panneau et le bord de l'écran (pixels)
  const SEUIL_DIAG_BAS = 15;              // angle (degrés au-dessus de l'horizontale) à partir duquel elle lève les bras en diagonale
  const SEUIL_DIAG_HAUT = 40;             // diagonale plus haute (environ 45 degrés)
  const SEUIL_BRAS_EN_L_AIR = 65;         // au-dessus : les deux mains en l'air
  const BULLE_REPONSE_MIN = 9000;         // temps minimal d'affichage de la réponse une fois écrite (ms)
  const BULLE_REPONSE_PAR_CARACTERE = 75; // temps de lecture ajouté par caractère (ms)
  const BULLE_REPONSE_MAX = 30000;        // temps maximal (ms)
  const BULLE_REPONSE_VITESSE = 22;       // vitesse d'écriture de la réponse (ms par caractère)
  const HAUTEUR_EPAULES = 0.73;           // hauteur de ses épaules (part de sa taille, depuis les pieds)
  const HAUTEUR_STANDARD = 540;           // taille de référence de ses images (pixels)
  const TEXTE_AIDE = "◼ MAINTIENS ET GLISSE LA TABLETTE VERS CAPRI  //  ENTRÉE = ENVOI DIRECT";
  const TAB_IMAGES = {"cote_droite": {"src": "capri_tab_cote_droite.png", "w": 419, "h": 545}, "cote_gauche": {"src": "capri_tab_cote_gauche.png", "w": 403, "h": 537}, "diag_haut": {"src": "capri_tab_diag_haut.png", "w": 389, "h": 564}, "diag_bas": {"src": "capri_tab_diag_bas.png", "w": 390, "h": 547}, "haut": {"src": "capri_tab_haut.png", "w": 303, "h": 580}, "lecture": {"src": "capri_tab_lecture.png", "w": 233, "h": 545, "mx": 0.661, "my": 0.318}};
  Object.keys(TAB_IMAGES).forEach((k) => precharge(TAB_IMAGES[k].src));

  const discBtn = document.getElementById('discBtn');
  const discPanel = document.getElementById('discPanel');
  const discInput = document.getElementById('discInput');
  const discCompress = document.getElementById('discCompress');
  const discFermer = document.getElementById('discFermer');
  const discHint = document.getElementById('discHint');
  const discTab = document.getElementById('discTab');
  const discTitre = document.getElementById('discTitre');
  discHint.textContent = TEXTE_AIDE;

  let panneauOuvert = false, survolBtn = false, survolPanneau = false;
  let tabActif = false;      // vrai tant qu'on tient la tablette
  let tabTenue = false;
  let tabX = 0, tabY = 0;    // position de la tablette
  let flipTablette = 1;      // sens de l'image de Capri (-1 = retournée)
  let tabCle = '';           // la pose actuelle
  let tabCentreX = 0;        // le centre de Capri (reste fixe pendant la discussion)
  let tabEpauleY = 0;        // la hauteur de ses épaules
  let flux = 0;              // change à chaque discussion (annule les anciennes)
  let rafVol = null, tabNettoyer = null, aideTimer = null, pointsTimer = null;
  let sourisX = -1, sourisY = -1;

  // Le clic ne traverse pas le bouton, le panneau ni la tablette tenue
  function uiCapte() { return survolBtn || survolPanneau || tabTenue; }

  window.addEventListener('pointermove', (e) => { sourisX = e.clientX; sourisY = e.clientY; }, true);
  function dansRect(el) {
    const r = el.getBoundingClientRect();
    return sourisX >= r.left && sourisX <= r.right && sourisY >= r.top && sourisY <= r.bottom;
  }

  // Place le bouton et le panneau dans le coin choisi
  function placerCoinDiscussion() {
    const haut = COIN_DISCUSSION.indexOf('haut') === 0;
    const gauche = COIN_DISCUSSION.indexOf('gauche') > 0;
    const m = MARGE_COIN + (haut && !gauche ? 50 : 0); // en haut à droite : sous les ports USB
    [discBtn, discPanel].forEach((el) => {
      el.style.top = haut ? m + 'px' : 'auto';
      el.style.bottom = haut ? 'auto' : MARGE_COIN + 'px';
      el.style.left = gauche ? MARGE_COIN + 'px' : 'auto';
      el.style.right = gauche ? 'auto' : MARGE_COIN + 'px';
    });
  }
  placerCoinDiscussion();

  discBtn.addEventListener('mouseenter', () => { survolBtn = true; majClic(); });
  discBtn.addEventListener('mouseleave', () => { survolBtn = false; majClic(); });
  discPanel.addEventListener('mouseenter', () => { survolPanneau = true; majClic(); });
  discPanel.addEventListener('mouseleave', () => { survolPanneau = false; majClic(); });

  // Affiché au début de la balade
  function montrerBoutonDiscussion() {
    placerCoinDiscussion();
    discPanel.style.display = 'none';
    panneauOuvert = false;
    discBtn.style.display = 'block';
    discBtn.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 600, delay: 500, fill: 'backwards' });
  }

  // Le panneau apparaît petit à petit, ligne par ligne
  function ouvrirPanneau() {
    if (!enAnim || panneauOuvert) return;
    panneauOuvert = true;
    discBtn.style.display = 'none';
    survolBtn = false;
    discPanel.getAnimations().forEach((a) => a.cancel());
    discPanel.style.display = 'block';
    survolPanneau = dansRect(discPanel);
    discPanel.animate([
      { clipPath: 'inset(0 0 100% 0)', opacity: 0.3 },
      { clipPath: 'inset(0 0 60% 0)', opacity: 1, offset: 0.45 },
      { clipPath: 'inset(0 0 0% 0)', opacity: 1 }
    ], { duration: 850, easing: 'steps(18)' });
    decoder(discTitre, 'LIEN CAPRI', 600);
    son('ouvre');
    setTimeout(() => { if (panneauOuvert) discInput.focus(); }, 500);
    majClic();
  }

  async function fermerPanneau() {
    if (!panneauOuvert) return;
    panneauOuvert = false;
    survolPanneau = false;
    try {
      await discPanel.animate([
        { clipPath: 'inset(0 0 0% 0)', opacity: 1 },
        { clipPath: 'inset(0 0 100% 0)', opacity: 0.3 }
      ], { duration: 260, easing: 'steps(8)', fill: 'forwards' }).finished;
    } catch (e) { return; }
    if (panneauOuvert) return;
    discPanel.style.display = 'none';
    discPanel.getAnimations().forEach((a) => a.cancel());
    if (enAnim) { discBtn.style.display = 'block'; survolBtn = dansRect(discBtn); }
    majClic();
  }

  discBtn.addEventListener('click', ouvrirPanneau);
  discFermer.addEventListener('click', fermerPanneau);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && panneauOuvert && !tabActif) fermerPanneau(); });

  // Message d'avertissement dans le panneau (il tremble)
  function signalerPanneau(msg) {
    discHint.textContent = msg;
    discHint.classList.add('mal');
    discPanel.animate([
      { transform: 'translateX(0px)' }, { transform: 'translateX(-7px)' }, { transform: 'translateX(6px)' },
      { transform: 'translateX(-4px)' }, { transform: 'translateX(0px)' }
    ], { duration: 260 });
    son('echec');
    clearTimeout(aideTimer);
    aideTimer = setTimeout(() => { discHint.textContent = TEXTE_AIDE; discHint.classList.remove('mal'); }, 1900);
  }

  // Place la tablette (x, y = son centre)
  function placerTab(x, y, rotation, k) {
    discTab.style.transform = 'translate(' + x.toFixed(1) + 'px,' + y.toFixed(1) + 'px) rotate(' + rotation.toFixed(1) +
      'deg) scale(' + (k === undefined ? 1 : k).toFixed(3) + ')';
  }

  // Le panneau se comprime vers son coin en haut à droite, en noircissant
  async function comprimerPanneau() {
    discPanel.getAnimations().forEach((a) => a.cancel());
    const a = discPanel.animate([
      { transform: 'scale(1, 1)', opacity: 1, filter: 'none' },
      { transform: 'scale(1.04, 0.88)', filter: 'brightness(1.8)', offset: 0.18 },
      { transform: 'scale(0.5, 0.28)', filter: 'brightness(0.3)', opacity: 1, offset: 0.6 },
      { transform: 'scale(0.14, 0.1)', filter: 'brightness(0)', opacity: 0.9, offset: 0.9 },
      { transform: 'scale(0.05, 0.04)', filter: 'brightness(0)', opacity: 0 }
    ], { duration: 420, easing: 'ease-in', fill: 'forwards' });
    try { await a.finished; } catch (e) { return; }
    discPanel.style.display = 'none';
    a.cancel();
    if (enAnim && !panneauOuvert) { discBtn.style.display = 'block'; survolBtn = dansRect(discBtn); majClic(); }
  }

  // ----- Capri se prépare : elle arrête ce qu'elle faisait et reste sur place -----
  function prendreCapri() {
    session++;
    cancelAnimationFrame(raf);
    sprite.getAnimations().forEach((a) => a.cancel());
    walker.getAnimations().forEach((a) => a.cancel());
    sprite.style.transform = '';
    walker.style.opacity = 1;
    walker.style.transformOrigin = '';
    walker.style.pointerEvents = '';
    cacherBulle();
    ligne = null; ipcRenderer.send('ligne-finie');
    fenetre = null; fermeeEnAttente = false; lignePerdue = false;
    etat = 'tablette';
    pose = 'tablette';
    rot = 0; phi = 0; omega = 0;
    tabCle = '';
    tabCentreX = ax + sprite.offsetWidth / 2;
    tabEpauleY = (window.innerHeight - ay) - HAUTEUR_EPAULES * HAUTEUR_STANDARD * ECHELLE;
    raf = requestAnimationFrame(boucle);
  }

  // Change l'image de Capri (en gardant son centre au même endroit)
  function poserTablette(cle, flip) {
    const k = cle + (flip < 0 ? '-' : '+');
    if (k === tabCle) return;
    tabCle = k;
    const d = TAB_IMAGES[cle];
    sprite.src = d.src;
    sprite.style.height = d.h * ECHELLE + 'px';
    sprite.style.width = d.w * ECHELLE + 'px';
    flipTablette = flip;
    ax = tabCentreX - d.w * ECHELLE / 2;
    majTransform(flip);
  }

  // Elle tend les bras vers la tablette : la pose dépend de l'angle entre ses épaules et la tablette
  function viser(x, y) {
    const dx = x - tabCentreX, dy = tabEpauleY - y;
    if (tabCle !== '' && Math.hypot(dx, dy) < 60) return;   // la tablette est contre elle : on ne change plus
    const droite = dx >= 0;
    const ang = Math.atan2(dy, Math.abs(dx)) * 180 / Math.PI;
    if (ang >= SEUIL_BRAS_EN_L_AIR) poserTablette('haut', 1);
    else if (ang >= SEUIL_DIAG_HAUT) poserTablette('diag_haut', droite ? -1 : 1);
    else if (ang >= SEUIL_DIAG_BAS) poserTablette('diag_bas', droite ? -1 : 1);
    else poserTablette(droite ? 'cote_droite' : 'cote_gauche', 1);
  }

  // L'endroit où la tablette arrive dans ses mains (quand elle lit)
  function mainsCapri() {
    const d = TAB_IMAGES.lecture;
    const W = d.w * ECHELLE, H = d.h * ECHELLE;
    return { x: tabCentreX - W / 2 + d.mx * W, y: (window.innerHeight - ay) - H + d.my * H };
  }

  // La tablette vole jusqu'à Capri, qui suit des bras
  function volerVersCapri(monFlux, s) {
    return new Promise((res) => {
      const x0 = tabX, y0 = tabY;
      const cible = mainsCapri();
      const dist = Math.hypot(cible.x - x0, cible.y - y0);
      const D = borner(380 + dist * 0.4, 450, 1200);
      const t0 = performance.now();
      const tick = (now) => {
        if (monFlux !== flux || s !== session) { res(false); return; }
        const p = Math.min(1, (now - t0) / D);
        const e = lisse(p);
        const x = x0 + (cible.x - x0) * e;
        const y = y0 + (cible.y - y0) * e - Math.sin(Math.PI * p) * Math.min(90, dist * 0.18);
        placerTab(x, y, -8 * (1 - e), 1 - 0.25 * e);
        viser(x, y);
        if (p >= 1) { res(true); return; }
        rafVol = requestAnimationFrame(tick);
      };
      rafVol = requestAnimationFrame(tick);
    });
  }

  // La bulle avec trois points qui bougent pendant que Capri "lit"
  function bulleAttente(s) {
    const id = ++bulleId;
    bulle.getAnimations().forEach((a) => a.cancel());
    bulleActive = true;
    bulleTxt.classList.remove('longue');
    bulleTxt.textContent = '·';
    bulle.style.display = 'block';
    positionnerBulle();
    let n = 0;
    clearInterval(pointsTimer);
    pointsTimer = setInterval(() => {
      if (id !== bulleId || s !== session) { clearInterval(pointsTimer); return; }
      n = (n + 1) % 3;
      bulleTxt.textContent = '·'.repeat(n + 1);
    }, 350);
  }

  // Comme direPhrase, mais avec un texte précis, plus large, et un temps d'affichage réglable
  async function direTexte(texte, duree, fondu, vitesse) {
    const id = ++bulleId;
    bulle.getAnimations().forEach((a) => a.cancel());
    bulleActive = true;
    bulleTxt.classList.add('longue');
    bulleTxt.textContent = '';
    bulle.style.display = 'block';
    positionnerBulle();
    bulle.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 120 });
    for (const c of texte) {
      if (id !== bulleId) return false;
      bulleTxt.textContent += c;
      await wait(vitesse);
    }
    await wait(duree);
    if (id !== bulleId) return false;
    try {
      await bulle.animate([{ opacity: 1 }, { opacity: 0 }], { duration: fondu, fill: 'forwards' }).finished;
    } catch (e) { return false; }
    if (id !== bulleId) return false;
    cacherBulle();
    return true;
  }

  // Une fois la réponse lue, elle repart (au sol : elle marche ; sur une fenêtre : elle redescend)
  async function finDiscussion(s) {
    if (s !== session) return;
    if (ay < 2) {
      adir = Math.random() < 0.5 ? -1 : 1;
      const ok = await transformer(MARCHE, s);
      if (!ok) return;
      etat = 'marche';
      const t = performance.now();
      finEtat = t + alea(4000, 9000);
      prochaineEscapade = t + alea(ESCAPADE_MIN, ESCAPADE_MAX);
      prochaineBulle = t + alea(BULLE_MIN, BULLE_MAX);
    } else {
      retourAuSol();
    }
  }

  // La tablette est lâchée : elle vole vers Capri, qui la lit, demande à l'IA, puis répond dans une bulle
  async function lancerEnvoi(monFlux, s, texte) {
    const encore = () => monFlux === flux && s === session;
    try {
      const ok = await volerVersCapri(monFlux, s);
      if (!ok || !encore()) return;

      // Elle attrape la tablette
      discTab.style.display = 'none';
      poserTablette('lecture', 1);
      walker.animate([{ filter: 'brightness(2.2)' }, { filter: 'none' }], { duration: 260 });
      const m = mainsCapri();
      particules(m.x, m.y, {
        couleurs: ['#27e6ff', '#00ffa3', '#ffffff'], n: 12, vmin: 80, vmax: 300,
        tailleMin: 2, tailleMax: 4, angleMin: -Math.PI, angleMax: Math.PI, duree: 420
      });
      son('connecte');
      await wait(350);
      if (!encore()) return;

      // Elle lit pendant que l'IA réfléchit
      bulleAttente(s);
      const reply = await ipcRenderer.invoke('ask', history.concat([{ role: 'user', content: texte }]));
      if (!encore()) return;
      const erreur = reply.startsWith('[Erreur');
      if (!erreur) {
        history.push({ role: 'user', content: texte });
        history.push({ role: 'assistant', content: reply });
        while (history.length > 20) history.splice(0, 2);
      }
      // La discussion apparaît aussi dans la fenêtre d'appel
      addRow('moi').textContent = texte;
      addRow('capri').textContent = reply;

      const aDire = erreur ? "Pas de signal, choom... Ollama est bien lancé ?" : reply;
      const duree = Math.min(BULLE_REPONSE_MAX, Math.max(BULLE_REPONSE_MIN, aDire.length * BULLE_REPONSE_PAR_CARACTERE));
      const fini = await direTexte(aDire, duree, 1200, BULLE_REPONSE_VITESSE);
      if (!fini || !encore()) return;
      await finDiscussion(s);
    } finally {
      if (monFlux === flux) discTab.style.display = 'none';
    }
  }

  // On appuie sur le bouton de compression : le panneau devient une tablette que l'on tient
  // (auto = true : envoi direct avec Entrée, la tablette part toute seule)
  function demarrerTablette(px, py, auto) {
    if (!enAnim || tabActif || !panneauOuvert) return;
    const texte = discInput.value.trim();
    if (!texte) { signalerPanneau("ÉCRIS D'ABORD UN MESSAGE..."); discInput.focus(); return; }
    if (occupee() && etat !== 'tablette') { signalerPanneau('CAPRI EST OCCUPÉE... RÉESSAIE DANS UN INSTANT'); return; }

    const monFlux = ++flux;
    tabActif = true;
    tabTenue = true;
    panneauOuvert = false;
    survolPanneau = false;
    discInput.value = '';
    discInput.blur();
    prendreCapri();
    const s = session;
    tabX = px; tabY = py;
    discTab.style.display = 'block';
    placerTab(px, py, -8, 1);
    discTab.animate([{ scale: 0.3, opacity: 0 }, { scale: 1, opacity: 1 }], { duration: 220 });
    comprimerPanneau();
    son('clic');
    viser(px, py);
    majClic();

    if (auto) {
      tabTenue = false; tabActif = false; majClic();
      lancerEnvoi(monFlux, s, texte);
      return;
    }

    const bouge = (m) => {
      tabX = m.clientX; tabY = m.clientY;
      placerTab(tabX, tabY, -8, 1);
      viser(tabX, tabY);
    };
    const retirer = () => {
      window.removeEventListener('pointermove', bouge);
      window.removeEventListener('pointerup', fin);
      window.removeEventListener('pointercancel', fin);
      tabNettoyer = null;
    };
    const fin = () => {
      retirer();
      tabTenue = false; tabActif = false;
      majClic();
      lancerEnvoi(monFlux, s, texte);
    };
    window.addEventListener('pointermove', bouge);
    window.addEventListener('pointerup', fin);
    window.addEventListener('pointercancel', fin);
    tabNettoyer = retirer;
  }

  discCompress.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    e.preventDefault();
    demarrerTablette(e.clientX, e.clientY, false);
  });
  discInput.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' || e.shiftKey) return;
    e.preventDefault();
    const r = discCompress.getBoundingClientRect();
    demarrerTablette(r.left + r.width / 2, r.top + r.height / 2, true);
  });

  // Fin de la balade : tout est remis à zéro
  function nettoyerDiscussion() {
    flux++;
    if (tabNettoyer) tabNettoyer();
    cancelAnimationFrame(rafVol);
    clearInterval(pointsTimer);
    clearTimeout(aideTimer);
    discPanel.getAnimations().forEach((a) => a.cancel());
    discTab.getAnimations().forEach((a) => a.cancel());
    discBtn.getAnimations().forEach((a) => a.cancel());
    discBtn.style.display = 'none';
    discPanel.style.display = 'none';
    discTab.style.display = 'none';
    discHint.textContent = TEXTE_AIDE;
    discHint.classList.remove('mal');
    panneauOuvert = false; tabActif = false; tabTenue = false;
    survolBtn = false; survolPanneau = false;
  }
`;

// ---------- Les modifications (chaque repère doit exister une seule fois) ----------
const MODIFS = [
  { nom: 'CSS', repere: '</style>', par: (r) => CSS + r },
  { nom: 'HTML', repere: '<div id="flashUsb"></div>', par: (r) => r + '\n' + HTML },
  { nom: 'JavaScript', repere: '</script>', par: (r) => JS + '\n' + r },
  {
    nom: 'occupee()', repere: "etat === 'puce' || etat === 'reboot' || etat === 'bug';",
    par: () => "etat === 'puce' || etat === 'reboot' || etat === 'bug' || etat === 'tablette';"
  },
  {
    nom: 'clic sur Capri', repere: "if (etat === 'puce' || etat === 'reboot' || etat === 'bug') return;",
    par: () => "if (etat === 'puce' || etat === 'reboot' || etat === 'bug' || etat === 'tablette') return;"
  },
  {
    nom: 'clic à travers', repere: 'survolCapri || menuOuvert || tenue || survolPuce || puceTenue));',
    par: () => 'survolCapri || menuOuvert || tenue || survolPuce || puceTenue || uiCapte()));'
  },
  {
    nom: 'sens de Capri', repere: 'const flip = pose === MARCHE ? adir * SENS_MARCHE : 1;',
    par: () => "const flip = pose === MARCHE ? adir * SENS_MARCHE : (etat === 'tablette' ? flipTablette : 1);"
  },
  {
    nom: 'bulle qui reste', repere: "etat !== 'ecrasee' && etat !== 'bug') cacherBulle();",
    par: () => "etat !== 'ecrasee' && etat !== 'bug' && etat !== 'tablette') cacherBulle();"
  },
  {
    nom: 'bulle large', repere: "bulle.style.display = 'none';",
    par: (r) => r + " bulleTxt.classList.remove('longue');"
  },
  { nom: 'fin de balade', repere: 'nettoyerPuce();', par: (r) => r + ' nettoyerDiscussion();' },
  {
    nom: 'début de balade', repere: "document.body.classList.add('enAnim');",
    par: (r) => r + '\n    montrerBoutonDiscussion();'
  }
];

function compter(txt, sous) {
  let n = 0, i = -1;
  while ((i = txt.indexOf(sous, i + 1)) >= 0) n++;
  return n;
}

function main() {
  if (!fs.existsSync(FICHIER)) {
    console.log("✗ index.html est introuvable dans " + DOSSIER);
    console.log("  Mets ce fichier dans le même dossier que index.html, puis relance la commande.");
    process.exit(1);
  }
  const original = fs.readFileSync(FICHIER, 'utf8');
  if (original.indexOf(MARQUE) >= 0) {
    console.log('✓ Les modifications sont déjà appliquées dans index.html : rien à faire.');
    return;
  }
  const crlf = original.indexOf('\r\n') >= 0;
  let txt = original.replace(/\r\n/g, '\n');

  // Vérification avant de toucher à quoi que ce soit
  for (const m of MODIFS) {
    const n = compter(txt, m.repere);
    if (n !== 1) {
      console.log('✗ Modification annulée : le repère « ' + m.nom + ' » est trouvé ' + n + ' fois (il en faut exactement 1).');
      console.log('  Ton index.html a sans doute changé. Rien n\'a été modifié. Envoie-moi le message ci-dessus et je corrige.');
      process.exit(1);
    }
  }
  // On applique de la fin vers le début du fichier, pour que les positions restent justes
  const places = MODIFS.map((m) => ({ m, i: txt.indexOf(m.repere) })).sort((a, b) => b.i - a.i);
  for (const { m, i } of places) {
    txt = txt.slice(0, i) + m.par(m.repere) + txt.slice(i + m.repere.length);
  }
  if (crlf) txt = txt.replace(/\n/g, '\r\n');

  if (!fs.existsSync(SAUVEGARDE)) fs.writeFileSync(SAUVEGARDE, original);
  fs.writeFileSync(FICHIER, txt);
  for (const nom of Object.keys(IMAGES)) {
    fs.writeFileSync(path.join(DOSSIER, nom), Buffer.from(IMAGES[nom], 'base64'));
  }
  console.log('✓ index.html modifié (sauvegarde : index.html.avant-discussion.bak)');
  console.log('✓ ' + Object.keys(IMAGES).length + ' images de poses créées');
  console.log('→ Relance Capri, clique sur ANIMER : le bouton PARLER apparaît dans un coin de l\'écran.');
}

main();
